export const findMotion = (id: string) => motionPrompts.find((p) => p.id === id);
export const postUrl = (p: Pick<MotionPrompt, "handle" | "xId">) => `https://x.com/${p.handle}/status/${p.xId}`;
export const tagCount = (t: MotionTag) => motionPrompts.filter((p) => p.tags.includes(t)).length;
